// Hellfire: the PlayStation Doom fire, one byte of heat per cell, its spread
// rule in this file's JS and frameos.pixels writing the cells straight into
// the frame (no canvas, no SVG, no markup). The simulation runs at the
// frame's size over pixelSize, so a 480x480 panel at 4 is a 120x120 grid.
// On a SenseCAP Indicator (ESP32-S3) that is 13 frames a second, and 26 at
// 8 px, which is why the automatic cell size is 8 there and 4 elsewhere.

// Doom's 37 colors, black to white through the reds and yellows.
const FIRE = [
  0x070707, 0x1f0707, 0x2f0f07, 0x470f07, 0x571707, 0x671f07, 0x771f07, 0x8f2707, 0x9f2f07, 0xaf3f07,
  0xbf4707, 0xc74707, 0xdf4f07, 0xdf5707, 0xdf5707, 0xd75f07, 0xd75f07, 0xd7670f, 0xcf6f0f, 0xcf770f,
  0xcf7f0f, 0xcf8717, 0xc78717, 0xc78f17, 0xc7971f, 0xbf9f1f, 0xbf9f1f, 0xbfa727, 0xbfa727, 0xbfaf2f,
  0xb7af2f, 0xb7b72f, 0xb7b737, 0xcfcf6f, 0xdfdf9f, 0xefefc7, 0xffffff,
]
const PALETTES = {
  fire: FIRE,
  ice: FIRE.map((c) => ((c & 0xff) << 16) | (c & 0xff00) | (c >> 16)),
  toxic: FIRE.map((c) => (((c >> 8) & 0xff) << 16) | (((c >> 16) & 0xff) << 8) | (c & 0xff)),
}
const HOT = FIRE.length - 1

// What outlives a render while the interpreter does. An ESP32 short of
// memory drops the interpreter and the fire restarts from its warm-up.
let heat = null
let cols = 0
let rows = 0
let seed = 1

// One step of the spread: every cell hands its heat to a cell of the row
// above, drifting with the wind and cooling a little. This loop is the whole
// cost of a frame in an interpreter, so it is written for bytecodes: one flat
// pass, locals only, no branch. It runs from the top row down, as Doom's: a
// row hands its heat into a row already done, so heat climbs a row a step.
// The heat is a Uint8ClampedArray, so a cold cell cooling below 0 stays 0.
//
// Each cell's chance comes from a table, read at a new random offset each
// step: the drift (0..3) in the low two bits, the cooling (0..2) above them.
// The cooling is Doom's coin flip on a grid about as tall as Doom's, and more
// on a coarse one, so the flames reach about 40% of the way up at any cell
// size; at Doom's rate a 60-row grid (8 px cells on a 480 px panel) burned to
// the top. A write lands at an offset from the cell: at a row's end it spills
// into the next row, as Doom's did, and before the first cell a typed array
// ignores it. The same seed is the same fire on every frame type.
const RAND_SPREAD = 4096
let RAND = null

function nextSeed(s) {
  s ^= s << 13
  s ^= s >>> 17
  s ^= s << 5
  return s
}

function fillRand(cells, rows) {
  // Heat falls by `cool` a row on average: HOT / cool rows of flame.
  const cool = Math.max(0.25, Math.min(2, HOT / (0.4 * rows)))
  const extra = Math.floor(cool) // 0, 1 or 2 always...
  const chance = Math.round((cool - extra) * 256) // ...and one more this often in 256
  RAND = new Uint8Array(cells + RAND_SPREAD)
  let s = seed
  for (let i = 0; i < RAND.length; i++) {
    s = nextSeed(s)
    const cooling = Math.min(2, extra + (((s >>> 8) & 255) < chance ? 1 : 0))
    RAND[i] = (s & 3) | (cooling << 2)
  }
  seed = s
}

// The rows above `top` are cold, and a step only reaches the row above the
// first it runs (and, spilling at a row's start, a few cells before it): the
// pass starts at `top`, so the black sky over the flames costs nothing.
let top = 1

function spread(wind) {
  const h = heat
  const R = RAND
  const w = cols
  const up = wind - w
  seed = nextSeed(seed)
  const off = seed & (RAND_SPREAD - 1)
  const n = h.length
  let i = top * w
  const end = n - ((n - i) & 1)
  for (; i < end; i += 2) {
    let r = R[i + off]
    h[i - (r & 3) + up] = h[i] - (r >> 2)
    r = R[i + 1 + off]
    h[i + 1 - (r & 3) + up] = h[i + 1] - (r >> 2)
  }
  if (i < n) {
    const r = R[i + off]
    h[i - (r & 3) + up] = h[i] - (r >> 2)
  }
  // Where the next pass starts: the first warm cell this one could have
  // reached, or one row lower when the first row it ran is cold.
  const from = Math.max(0, (top - 1) * w - 6)
  let warm = -1
  for (let j = from; j < top * w; j++) {
    if (h[j] !== 0) {
      warm = j
      break
    }
  }
  if (warm >= 0) {
    top = Math.max(1, Math.floor(warm / w))
  } else if (top < rows - 1) {
    let cold = true
    for (let j = top * w, e = j + w; j < e; j++) {
      if (h[j] !== 0) {
        cold = false
        break
      }
    }
    if (cold) top++
  }
}

// The frame rate, counted over the last second of renders: what the panel
// really gets, simulation, blit and pacing included.
let fps = null
let frames = 0
let windowStart = 0

function countFrame() {
  const now = Date.now()
  if (!windowStart) windowStart = now
  frames++
  const elapsed = now - windowStart
  if (elapsed >= 1000) {
    fps = Math.round((frames * 1000) / elapsed)
    frames = 0
    windowStart = now
  }
  return fps
}

// The counter, in a 3x5 font, 15 bits a glyph, top row first. It goes into the
// heat for the blit and comes out before the next step: the same cheap write
// as the flames, so it does not slow what it measures, and it never feeds them.
const GLYPHS = {
  0: 0x7b6f, 1: 0x2c97, 2: 0x73e7, 3: 0x73cf, 4: 0x5bc9, 5: 0x79cf, 6: 0x79ef, 7: 0x7249, 8: 0x7bef, 9: 0x7bcf,
  '-': 0x01c0, F: 0x79e4, P: 0x7be4, S: 0x79cf,
}
let label = null
let labelText = ''
let labelScale = 0
let labelled = false
let labelWidth = 0
let labelHeight = 0
let under = null

function setLabel(text, scale) {
  if (text === labelText && scale === labelScale) return
  labelText = text
  labelScale = scale
  labelWidth = (text.length * 4 + 1) * scale
  labelHeight = 7 * scale
  label = new Uint8Array(labelWidth * labelHeight) // 0 is the fire's black
  under = new Uint8Array(labelWidth * labelHeight)
  for (let g = 0; g < text.length; g++) {
    const bits = GLYPHS[text[g]] || 0
    for (let i = 0; i < 15; i++) {
      if (!(bits & (1 << (14 - i)))) continue
      const left = (g * 4 + 1 + (i % 3)) * scale
      const top = (1 + Math.floor(i / 3)) * scale
      for (let y = 0; y < scale; y++) label.fill(HOT, (top + y) * labelWidth + left, (top + y) * labelWidth + left + scale)
    }
  }
}

function labelFits() {
  return labelWidth + labelScale <= cols && labelHeight + labelScale <= rows
}

function labelIn() {
  for (let y = 0; y < labelHeight; y++) {
    const at = (y + labelScale) * cols + labelScale
    under.set(heat.subarray(at, at + labelWidth), y * labelWidth)
    heat.set(label.subarray(y * labelWidth, (y + 1) * labelWidth), at)
  }
}

function labelOut() {
  for (let y = 0; y < labelHeight; y++) {
    heat.set(under.subarray(y * labelWidth, (y + 1) * labelWidth), (y + labelScale) * cols + labelScale)
  }
}

export function get(app, context) {
  if (labelled) labelOut() // the frame before this one has been written
  labelled = false
  const config = app.config
  const asked = Math.round(Number(config.pixelSize) || 0)
  const pixelSize = asked >= 1 ? Math.min(32, asked) : app.frame.embedded ? 8 : 4
  const width = Math.max(pixelSize, context.imageWidth || app.frame.width)
  const height = Math.max(pixelSize, context.imageHeight || app.frame.height)
  const palette = PALETTES[config.palette] || FIRE
  const wind = Math.max(-3, Math.min(3, Math.round(Number(config.wind) || 0)))
  const steps = Math.max(1, Math.min(500, Math.round(Number(config.stepsPerRender) || 1)))
  const w = Math.floor(width / pixelSize)
  const h = Math.floor(height / pixelSize)
  if (!heat || w !== cols || h !== rows) {
    cols = w
    rows = h
    heat = new Uint8ClampedArray(cols * rows)
    heat.fill(HOT, (rows - 1) * cols) // the bottom row burns
    const given = Math.round(Number(config.seed) || 0)
    seed = (given > 0 ? given : Date.now() ^ (Math.random() * 0x7fffffff)) | 0 || 1
    fillRand(cols * rows, rows)
    top = rows - 1
    // Warm up: heat climbs a row a step and the flames stand 40% of the way
    // up, so after this many the first frame is a fire, not a glowing line.
    // The sky is skipped (top), so the early steps are short.
    const climb = Math.ceil(rows * 0.6)
    for (let i = 0; i < climb; i++) spread(wind)
  } else {
    for (let i = 0; i < steps; i++) spread(wind)
  }
  const askedFps = config.showFps
  const showFps = askedFps === true || askedFps === 'true'
  if (showFps) {
    const rate = countFrame()
    setLabel((rate === null ? '--' : rate) + ' FPS', Math.ceil(4 / pixelSize))
    labelled = labelFits()
    if (labelled) labelIn()
  } else {
    frames = 0
    windowStart = 0
  }
  return frameos.pixels(heat, { width: cols, height: rows, pixelSize, palette })
}
